import { test, expect } from '@playwright/test';

test.describe('Responsive Font Size on Small Screen', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should display text in readable font size on small screen without zooming', async ({ page }) => {
    // Set up test environment
    await page.setViewportSize({ width: 320, height: 480 });

    // Verify page title is visible and readable
    const pageTitle = page.getByRole('heading', { name: /Welcome/i });
    await expect(pageTitle).toBeVisible();
    await expect(pageTitle).toHaveTextContent('Welcome');

    // Verify body text is readable
    const bodyText = page.getByText(/Welcome to our app/i);
    await expect(bodyText).toBeVisible();
    await expect(bodyText).toHaveTextContent('Welcome to our app');

    // Verify font size is not too small
    const fontSize = page.getByRole('heading', { name: /Welcome/i }).evaluate((el) => window.getComputedStyle(el).fontSize);
    expect(fontSize).toBeGreaterThan('12px');

    // Verify font size is not too large
    const maxFontSize = page.getByRole('heading', { name: /Welcome/i }).evaluate((el) => window.getComputedStyle(el).fontSize);
    expect(maxFontSize).toBeLessThan('24px');

    // Verify responsive font size adjustment
    await page.setViewportSize({ width: 640, height: 480 });
    const responsiveFontSize = page.getByRole('heading', { name: /Welcome/i }).evaluate((el) => window.getComputedStyle(el).fontSize);
    expect(responsiveFontSize).toBeGreaterThan('12px');
    expect(responsiveFontSize).toBeLessThan('24px');
  });

  test('should maintain readable font size when user zooms in on small screen', async ({ page }) => {
    // Set up test environment
    await page.setViewportSize({ width: 320, height: 480 });

    // Verify page title is visible and readable
    const pageTitle = page.getByRole('heading', { name: /Welcome/i });
    await expect(pageTitle).toBeVisible();
    await expect(pageTitle).toHaveTextContent('Welcome');

    // Verify body text is readable
    const bodyText = page.getByText(/Welcome to our app/i);
    await expect(bodyText).toBeVisible();
    await expect(bodyText).toHaveTextContent('Welcome to our app');

    // Verify font size is not too small
    const fontSize = page.getByRole('heading', { name: /Welcome/i }).evaluate((el) => window.getComputedStyle(el).fontSize);
    expect(fontSize).toBeGreaterThan('12px');

    // Verify font size is not too large
    const maxFontSize = page.getByRole('heading', { name: /Welcome/i }).evaluate((el) => window.getComputedStyle(el).fontSize);
    expect(maxFontSize).toBeLessThan('24px');

    // Zoom in using keyboard shortcut
    await page.keyboard.press('Ctrl+0');

    // Verify font size remains readable after zoom
    const zoomedFontSize = page.getByRole('heading', { name: /Welcome/i }).evaluate((el) => window.getComputedStyle(el).fontSize);
    expect(zoomedFontSize).toBeGreaterThan('12px');
    expect(zoomedFontSize).toBeLessThan('24px');

    // Verify text is still visible and readable
    await expect(pageTitle).toBeVisible();
    await expect(pageTitle).toHaveTextContent('Welcome');

    await expect(bodyText).toBeVisible();
    await expect(bodyText).toHaveTextContent('Welcome to our app');
  });
});
